using namespace std;

struct Point2d {
    double x() const { return 0; }
    double y() const { return 0; }
};

int computeAlphaShape2D(const std::vector<Point2d>& points, double alpha) {
    if (points.empty()) return 0;

    typedef CGAL::Exact_predicates_inexact_constructions_kernel K;
    typedef K::Point_2 CGALPoint;
    typedef CGAL::Alpha_shape_vertex_base_2<K> Vb;
    typedef CGAL::Alpha_shape_face_base_2<K> Fb;
    typedef CGAL::Triangulation_data_structure_2<Vb, Fb> Tds;
    typedef CGAL::Delaunay_triangulation_2<K, Tds> Triangulation_2;
    typedef CGAL::Alpha_shape_2<Triangulation_2> Alpha_shape_2;

    std::vector<CGALPoint> cgal_points;
    for (const auto& p : points) {
        cgal_points.emplace_back(p.x(), p.y());
    }

    Alpha_shape_2 as(cgal_points.begin(), cgal_points.end());
    as.set_alpha(alpha);

    int solid_components = 0;
    std::vector<Alpha_shape_2::Face_handle> faces;
    std::vector<bool> visited(as.number_of_faces(), false);

    for (Alpha_shape_2::Finite_faces_iterator it = as.finite_faces_begin(); it != as.finite_faces_end(); ++it) {
        if (as.classify(it) == Alpha_shape_2::INTERIOR) {
            Alpha_shape_2::Face_handle fh = it;
            if (!visited[fh->info()]) {
                solid_components++;
                std::queue<Alpha_shape_2::Face_handle> queue;
                queue.push(fh);
                visited[fh->info()] = true;

                while (!queue.empty()) {
                    Alpha_shape_2::Face_handle curr = queue.front();
                    queue.pop();

                    for (int i = 0; i < 3; ++i) {
                        Alpha_shape_2::Face_handle neighbor = curr->neighbor(i);
                        if (!as.is_infinite(neighbor) && 
                            as.classify(neighbor) == Alpha_shape_2::INTERIOR && 
                            !visited[neighbor->info()]) {
                            visited[neighbor->info()] = true;
                            queue.push(neighbor);
                        }
                    }
                }
            }
        }
    }

    return solid_components;
}

